<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Bouncing Ball Physics Playground</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    background: #0d0d0d;
    color: #e0e0e0;
    font-family: system-ui, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    gap: 16px;
    padding: 20px;
  }
  h1 { font-size: 1.4rem; color: #a78bfa; letter-spacing: 0.05em; }
  #sim {
    display: block;
    border: 2px solid #3f3f5a;
    border-radius: 8px;
    cursor: crosshair;
    box-shadow: 0 0 40px #4c1d9540;
  }
  .controls {
    display: flex;
    gap: 12px;
  }
  button {
    padding: 10px 24px;
    border: none;
    border-radius: 6px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    transition: opacity 0.15s, transform 0.1s;
  }
  button:active { transform: scale(0.96); }
  #drop { background: #7c3aed; color: #fff; }
  #drop:hover { background: #6d28d9; }
  #play { background: #065f46; color: #6ee7b7; }
  #play:hover { background: #047857; }
  #play.paused { background: #7c2d12; color: #fca5a5; }
  #play.paused:hover { background: #92400e; }
  #clear { background: #1f1f2e; color: #94a3b8; border: 1px solid #3f3f5a; }
  #clear:hover { background: #2d2d44; }
</style>
</head>
<body>
<h1>Bouncing Ball Physics Playground</h1>
<canvas id="sim" width="600" height="500"></canvas>
<div class="controls">
  <button id="drop">Drop Ball</button>
  <button id="play">Pause</button>
  <button id="clear">Clear</button>
</div>
<script>
(function() {
  const canvas = document.getElementById('sim');
  const ctx = canvas.getContext('2d');

  const W = canvas.width;
  const H = canvas.height;
  const GRAVITY = 0.4;
  const RESTITUTION = 0.78;
  const MIN_SPEED = 0.1;

  let balls = [];
  let running = true;
  let animId = null;

  const COLORS = [
    '#a78bfa', '#60a5fa', '#34d399', '#f472b6',
    '#fb923c', '#facc15', '#38bdf8', '#f87171'
  ];
  let colorIdx = 0;

  function randomColor() {
    return COLORS[colorIdx++ % COLORS.length];
  }

  function addBall(x, y, vx = 0, vy = 0, r) {
    if (r === undefined || r === null) r = 12 + Math.random() * 14;
    const ball = {
      x: Math.max(r, Math.min(W - r, x)),
      y: Math.max(r, Math.min(H - r, y)),
      vx,
      vy,
      r,
      color: randomColor()
    };
    balls.push(ball);
    return ball;
  }

  function clear() {
    balls = [];
    draw();
  }

  function step(dt = 1) {
    for (const b of balls) {
      b.vy += GRAVITY * dt;
      b.x += b.vx * dt;
      b.y += b.vy * dt;

      // floor
      if (b.y + b.r >= H) {
        b.y = H - b.r;
        b.vy = -Math.abs(b.vy) * RESTITUTION;
        if (Math.abs(b.vy) < MIN_SPEED) b.vy = 0;
      }
      // ceiling
      if (b.y - b.r <= 0) {
        b.y = b.r;
        b.vy = Math.abs(b.vy) * RESTITUTION;
      }
      // right wall
      if (b.x + b.r >= W) {
        b.x = W - b.r;
        b.vx = -Math.abs(b.vx) * RESTITUTION;
      }
      // left wall
      if (b.x - b.r <= 0) {
        b.x = b.r;
        b.vx = Math.abs(b.vx) * RESTITUTION;
      }
    }
    draw();
  }

  function draw() {
    ctx.fillStyle = '#0d0d17';
    ctx.fillRect(0, 0, W, H);

    // grid lines
    ctx.strokeStyle = '#1a1a2e';
    ctx.lineWidth = 1;
    for (let x = 0; x < W; x += 50) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, H); ctx.stroke();
    }
    for (let y = 0; y < H; y += 50) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke();
    }

    for (const b of balls) {
      const grad = ctx.createRadialGradient(
        b.x - b.r * 0.3, b.y - b.r * 0.3, b.r * 0.1,
        b.x, b.y, b.r
      );
      grad.addColorStop(0, '#ffffff55');
      grad.addColorStop(0.4, b.color + 'cc');
      grad.addColorStop(1, b.color + '66');

      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      ctx.fillStyle = grad;
      ctx.fill();

      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      ctx.strokeStyle = b.color;
      ctx.lineWidth = 1.5;
      ctx.stroke();
    }
  }

  function loop() {
    if (running) step(1);
    animId = requestAnimationFrame(loop);
  }

  // Controls
  document.getElementById('drop').addEventListener('click', () => {
    const x = W / 2 + (Math.random() - 0.5) * 100;
    addBall(x, 30, (Math.random() - 0.5) * 4, 0);
  });

  const playBtn = document.getElementById('play');
  playBtn.addEventListener('click', () => {
    running = !running;
    if (running) {
      playBtn.textContent = 'Pause';
      playBtn.classList.remove('paused');
    } else {
      playBtn.textContent = 'Play';
      playBtn.classList.add('paused');
    }
  });

  document.getElementById('clear').addEventListener('click', clear);

  canvas.addEventListener('click', (e) => {
    const rect = canvas.getBoundingClientRect();
    const scaleX = W / rect.width;
    const scaleY = H / rect.height;
    const x = (e.clientX - rect.left) * scaleX;
    const y = (e.clientY - rect.top) * scaleY;
    addBall(x, y, (Math.random() - 0.5) * 6, -2);
  });

  // Public API
  window.sim = {
    get w() { return W; },
    get h() { return H; },
    balls() { return balls.map(b => ({ x: b.x, y: b.y, vx: b.vx, vy: b.vy, r: b.r })); },
    addBall,
    clear,
    step
  };

  draw();
  loop();
})();
</script>
</body>
</html>
